"""### Step 2: connect your Google Colab notebook to your existing Snowflake account.

Step 2.1 – Store Snowflake credentials in Colab: keys

Step 2.2 – Connect to Snowflake
"""

import snowflake.connector
from google.colab import userdata

# Read credentials securely from Colab Secrets
conn = snowflake.connector.connect(
    account=userdata.get("SNOWFLAKE_ACCOUNT"),
    user=userdata.get("SNOWFLAKE_USER"),
    password=userdata.get("SNOWFLAKE_PASSWORD"),
    warehouse=userdata.get("SNOWFLAKE_WAREHOUSE")
)

print("Successfully connected to Snowflake!")

"""Step 2.3 – Test the connection"""

cursor = conn.cursor()

cursor.execute("SELECT CURRENT_VERSION(), CURRENT_USER(), CURRENT_WAREHOUSE()")

result = cursor.fetchone()

print("Snowflake Version:", result[0])
print("Current User:", result[1])
print("Current Warehouse:", result[2])

"""Step 2.4 – Create and select a Snowflake warehouse"""

# Create a small warehouse for our FreshCart project

cursor.execute("""
CREATE WAREHOUSE IF NOT EXISTS FRESHCART_WH
WITH
    WAREHOUSE_SIZE = 'XSMALL'
    AUTO_SUSPEND = 60
    AUTO_RESUME = TRUE
    INITIALLY_SUSPENDED = FALSE
""")

print("FreshCart warehouse created successfully!")

