"""### Step 3 – Create the FreshCart database and schemas

3.1 Create the database
"""

cursor.execute("""
CREATE DATABASE IF NOT EXISTS FRESHCART_DB
""")

cursor.execute("USE DATABASE FRESHCART_DB")

print("Database FRESHCART_DB is ready!")

"""3.2 Create the schemas"""

# Create schemas for the ELT pipeline

schemas = ["BRONZE", "SILVER", "DIM", "REF", "GOLD"]

for schema in schemas:
    cursor.execute(f"""
        CREATE SCHEMA IF NOT EXISTS FRESHCART_DB.{schema}
    """)
    print(f"{schema} schema created successfully!")

"""3.3 Verify the schemas"""

cursor.execute("SHOW SCHEMAS IN DATABASE FRESHCART_DB")

for row in cursor.fetchall():
    print(row[1])

