"""Verify actual row counts"""

from google.colab import userdata
import snowflake.connector

conn = snowflake.connector.connect(
    account=userdata.get("SNOWFLAKE_ACCOUNT"),
    user=userdata.get("SNOWFLAKE_USER"),
    password=userdata.get("SNOWFLAKE_PASSWORD"),
    warehouse="FRESHCART_WH",
    database="FRESHCART_DB"
)

cur = conn.cursor()

tables = [
    "BRONZE.ORDERS_RAW",
    "BRONZE.CUSTOMERS_RAW",
    "BRONZE.FX_RAW",
    "BRONZE.PINCODE_RAW",
    "SILVER.ORDERS_CHECKED",
    "SILVER.ORDERS_CLEAN",
    "SILVER.ORDERS_DEDUP",
    "SILVER.ORDERS_ENRICHED",
    "QUARANTINE.ORDERS",
    "GOLD.FCT_ORDERS"
]

print("FRESHCART TABLE ROW COUNTS")
print("-" * 40)

for table in tables:
    cur.execute(f"SELECT COUNT(*) FROM FRESHCART_DB.{table}")
    count = cur.fetchone()[0]
    print(f"{table}: {count}")

cur.close()
conn.close()

