"""Verify Gold revenue and loyalty points"""

from google.colab import userdata
import snowflake.connector

conn = snowflake.connector.connect(
    account=userdata.get("SNOWFLAKE_ACCOUNT"),
    user=userdata.get("SNOWFLAKE_USER"),
    password=userdata.get("SNOWFLAKE_PASSWORD"),
    warehouse="FRESHCART_WH",
    database="FRESHCART_DB"
)

cur = conn.cursor()

cur.execute("""
SELECT
    COUNT(*) AS TOTAL_ORDERS,
    SUM(AMOUNT_INR) AS TOTAL_REVENUE_INR,
    SUM(LOYALTY_POINTS) AS TOTAL_LOYALTY_POINTS
FROM GOLD.FCT_ORDERS
""")

result = cur.fetchone()

print("GOLD BUSINESS SUMMARY")
print("------------------------------")
print("Total Orders:", result[0])
print("Total Revenue (INR):", result[1])
print("Total Loyalty Points:", result[2])

cur.close()
conn.close()

